const TOOL_BY_LANG = (r: RecipeRaw, language: Language) =>
  language === 'es' ? r.toolEs : language === 'pt' ? r.toolPt : language === 'fr' ? r.toolEn : language === 'de' ? r.toolEn : language === 'en' ? r.toolEn : r.toolNl;

const INGREDIENTS_BY_LANG = (r: RecipeRaw, language: Language) =>
  language === 'es' ? r.ingredientsEs : language === 'pt' ? r.ingredientsPt : language === 'fr' ? r.ingredientsEn : language === 'de' ? r.ingredientsEn : language === 'en' ? r.ingredientsEn : r.ingredientsNl;

export function useRecipes(): RecipeItem[] {
  const { language } = useLanguage();
  return useMemo(
    () =>
      RECIPES_RAW.map((r) => ({
    name: language === 'es' ? r.nameEs : language === 'pt' ? r.namePt : language === 'fr' ? r.nameFr : language === 'de' ? r.nameDe : r.nameEn,
    rarity: language === 'es' ? r.rarityEs : language === 'pt' ? r.rarityPt : r.rarityEn,
    tool: TOOL_BY_LANG(r, language),
    ingredients: INGREDIENTS_BY_LANG(r, language),
    level: r.level,
    rarityColorKey: r.rarityColorKey,
    xp: r.xp,
    emoji: r.emoji,
    sellPriceByStar: r.sellPriceByStar,
      })),
    [language]
  );
}
